  "settings.write": ALL,
  "plans.read": ALL,
  "team.read": ALL,
  "team.update": ADMINS,
  "team.invite": ADMINS,
  "team.removeMember": ADMINS,
  "member.read": ALL,
  "shift.read": ALL,
  "shift.create": SCHEDULERS,
  "shift.update": SCHEDULERS,
  "shift.delete": SCHEDULERS,
  "shift.respond": ALL,
  "swap.read": ALL,
  "swap.request": ALL,
