    const removed = await cleanupExpiredIdempotency(deps.topology.global);
    if (removed > 0) ctx.log.info({ removed }, "expired idempotency keys cleaned");
    await queue.add(RENEWALS_QUEUE, {}, { delayMs: RENEWAL_SWEEP_MS, attempts: 5 });
